//! Precomputed fixed-base comb table for the Confidential Transactions
//! second generator `H` ([`super::pedersen::Generator::h`]).
//!
//! `ZKP_H_TABLE[i][j - 1]` is the affine point `[j * 16^i]H` for `i in 0..64`,
//! `j in 1..=15`, stored as `[x_0, x_1, x_2, x_3, y_0, y_1, y_2, y_3]` —
//! little-endian 64-bit limbs of the x then y coordinates, as **plain
//! residues in `[0, p)`** — the layout of the secp256k1 generator table
//! (`CombTable`), so the same constant-time signed-digit comb serves both
//! bases. No entry is the identity (`j * 16^i` is never a multiple of the odd
//! prime group order `n`), so a plain `Z = 1` lift is always valid. ~61 KB,
//! behind the `zkp-h-table` feature.
//!
//! Generated by the `#[ignore]`d test `zkp::pedersen::tests::gen_zkp_h_table`
//! (`cargo test --release gen_zkp_h_table -- --ignored --nocapture`); the
//! always-run test `zkp::pedersen::tests::h_table_matches_computed`
//! re-derives every entry from the group law on each test run, so these
//! constants are verified, not trusted.

